        _e("kv_ml_finetuning", "LLM Fine-Tuning", "ml", "# Full fine-tuning vs LoRA vs QLoRA\n\nFull: update all weights — expensive, needs lots of data\nLoRA: Low-Rank Adaptation — add small trainable matrices\nQLoRA: Quantized LoRA — 4-bit base model + LoRA\n\n# Hugging Face + PEFT\nfrom peft import LoraConfig, get_peft_model\nfrom transformers import AutoModelForCausalLM, TrainingArguments, Trainer\n\nmodel = AutoModelForCausalLM.from_pretrained('meta-llama/Llama-2-7b', load_in_4bit=True)\nlora_config = LoraConfig(r=16, lora_alpha=32, target_modules=['q_proj','v_proj'], lora_dropout=0.05)\nmodel = get_peft_model(model, lora_config)\n\ntrainer = Trainer(\n    model=model, train_dataset=dataset,\n    args=TrainingArguments(output_dir='./out', num_train_epochs=3, per_device_train_batch_size=4,\n                           learning_rate=2e-4, fp16=True, logging_steps=10)\n)\ntrainer.train()\n\n# Data format: instruction-following\n{'instruction': 'Summarize this article', 'input': 'article text...', 'output': 'summary...'}\n\n# Key: quality data > quantity, eval on held-out set, avoid catastrophic forgetting", ["ml","fine-tuning","lora","qlora","llm","peft","huggingface"]),
