        _e("kv_haskell", "Haskell Fundamentals", "haskell", "-- Pure functional, strongly typed, lazy evaluation\n\n-- Functions\nadd :: Int -> Int -> Int\nadd x y = x + y\n\n-- Pattern matching\nfactorial :: Integer -> Integer\nfactorial 0 = 1\nfactorial n = n * factorial (n - 1)\n\n-- List operations\ndoubleAll = map (*2) [1..10]  -- [2,4,6,...,20]\nevens = filter even [1..20]\nsum' = foldl (+) 0 [1..100]   -- 5050\n\n-- Algebraic data types\ndata Shape = Circle Double | Rectangle Double Double\narea :: Shape -> Double\narea (Circle r) = pi * r * r\narea (Rectangle w h) = w * h\n\n-- Maybe monad (null safety)\nsafeDivide :: Double -> Double -> Maybe Double\nsafeDivide _ 0 = Nothing\nsafeDivide x y = Just (x / y)\n\n-- IO monad\nmain :: IO ()\nmain = do\n    putStrLn \"What is your name?\"\n    name <- getLine\n    putStrLn (\"Hello, \" ++ name)\n\n-- Type classes: Eq, Ord, Show, Functor, Applicative, Monad", ["haskell","functional","monad","pattern-matching","pure"]),
        _e("kv_elixir", "Elixir & Phoenix", "elixir", "# Pattern matching\n{:ok, result} = {:ok, 42}  # result = 42\n[head | tail] = [1, 2, 3]  # head = 1, tail = [2,3]\n\n# Pipe operator\n\"hello world\"\n|> String.split()\n|> Enum.map(&String.capitalize/1)\n|> Enum.join(\" \")  # \"Hello World\"\n\n# Processes (lightweight, millions possible)\nspawn(fn -> IO.puts(\"Hello from process\") end)\npid = spawn(fn -> receive do {:msg, text} -> IO.puts(text) end end)\nsend(pid, {:msg, \"Hi!\"})\n\n# GenServer\ndefmodule Counter do\n  use GenServer\n  def init(count), do: {:ok, count}\n  def handle_call(:get, _from, count), do: {:reply, count, count}\n  def handle_cast(:inc, count), do: {:noreply, count + 1}\nend\n\n# Phoenix Framework\n# Channels for real-time (WebSocket)\n# LiveView: server-rendered interactive UIs\n# Ecto: database wrapper (like ActiveRecord)\n# Supervision trees: self-healing processes", ["elixir","phoenix","erlang","concurrency","pipe","genserver"]),
        _e("kv_scala", "Scala Essentials", "scala", "// Variables\nval name: String = \"Alice\"  // immutable\nvar age: Int = 30           // mutable\n\n// Functions\ndef add(a: Int, b: Int): Int = a + b\nval double = (x: Int) => x * 2  // lambda\n\n// Collections\nval nums = List(1, 2, 3, 4, 5)\nnums.filter(_ % 2 == 0).map(_ * 2)  // List(4, 8)\nnums.foldLeft(0)(_ + _)  // 15\n\n// Pattern matching\nval result = x match {\n  case 1 => \"one\"\n  case s: String => s\"got string: $s\"\n  case _ => \"other\"\n}\n\n// Case classes (like data classes)\ncase class User(name: String, age: Int)\nval u = User(\"Alice\", 30)\nval u2 = u.copy(age = 31)\n\n// Traits (like interfaces with implementation)\ntrait Printable { def print(): Unit = println(this.toString) }\n\n// For comprehension (flatMap/map sugar)\nfor {\n  user <- getUser(id)\n  posts <- getPosts(user.id)\n} yield (user, posts)\n\n// Akka: actor-based concurrency\n// Spark: written in Scala, big data processing", ["scala","jvm","functional","pattern-matching","case-class","akka"]),
        _e("kv_zig", "Zig Programming", "zig", "const std = @import(\"std\");\n\npub fn main() !void {\n    const stdout = std.io.getStdOut().writer();\n    try stdout.print(\"Hello, {}!\\n\", .{\"world\"});\n}\n\n// Comptime (compile-time execution)\nfn fibonacci(comptime n: u64) u64 {\n    if (n <= 1) return n;\n    return fibonacci(n - 1) + fibonacci(n - 2);\n}\nconst fib10 = fibonacci(10);  // computed at compile time\n\n// Optional types (null safety)\nvar x: ?i32 = null;\nif (x) |value| { use(value); }\nconst y = x orelse 0;\n\n// Error handling\nfn divide(a: f64, b: f64) !f64 {\n    if (b == 0) return error.DivisionByZero;\n    return a / b;\n}\nconst result = divide(10, 3) catch |err| handleError(err);\n\n// No hidden allocations, no hidden control flow\n// Manual memory management with allocators\n// C interop without FFI overhead\n// Used in: Bun (JS runtime), game engines, systems programming", ["zig","systems","comptime","error-handling","memory"]),

        # ═══ WEB SCRAPING & AUTOMATION ═══
        _e("kv_scraping", "Web Scraping", "python", "import requests\nfrom bs4 import BeautifulSoup\nimport json\n\n# Simple scraping\nres = requests.get('https://example.com', headers={'User-Agent': 'Mozilla/5.0'})\nsoup = BeautifulSoup(res.text, 'html.parser')\ntitles = [h2.text for h2 in soup.find_all('h2', class_='title')]\nlinks = [a['href'] for a in soup.find_all('a', href=True)]\n\n# CSS selectors\nprices = soup.select('.product .price')\nrows = soup.select('table tbody tr')\n\n# Async scraping\nimport aiohttp, asyncio\nasync def fetch(session, url):\n    async with session.get(url) as resp:\n        return await resp.text()\n\nasync def scrape_all(urls):\n    async with aiohttp.ClientSession() as session:\n        tasks = [fetch(session, url) for url in urls]\n        return await asyncio.gather(*tasks)\n\n# Playwright for JS-rendered pages\nfrom playwright.sync_api import sync_playwright\nwith sync_playwright() as p:\n    page = p.chromium.launch().new_page()\n    page.goto('https://spa-site.com')\n    page.wait_for_selector('.data')\n    content = page.content()\n\n# Ethics: respect robots.txt, rate limit, don't overload servers", ["python","scraping","beautifulsoup","playwright","automation"]),
        _e("kv_py_concurrency", "Python Concurrency", "python", "import threading, multiprocessing, asyncio, concurrent.futures\n\n# Threading (I/O-bound: network, file, DB)\ndef fetch(url):\n    return requests.get(url).text\n\nwith concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:\n    results = list(executor.map(fetch, urls))\n\n# Multiprocessing (CPU-bound: math, image processing)\ndef heavy_compute(n):\n    return sum(i**2 for i in range(n))\n\nwith multiprocessing.Pool(4) as pool:\n    results = pool.map(heavy_compute, [10**6]*4)\n\n# asyncio (I/O-bound, single-threaded)\nasync def fetch_all(urls):\n    async with aiohttp.ClientSession() as session:\n        tasks = [session.get(url) for url in urls]\n        return await asyncio.gather(*tasks)\n\n# GIL: Global Interpreter Lock\n# Only one thread executes Python bytecode at a time\n# Threading works for I/O (releases GIL during wait)\n# Multiprocessing bypasses GIL (separate processes)\n# asyncio: cooperative multitasking, best for many I/O operations\n\n# Rule: I/O-bound → asyncio/threading, CPU-bound → multiprocessing", ["python","concurrency","threading","multiprocessing","asyncio","gil"]),

        # ═══ REGEX ADVANCED ═══
        _e("kv_regex_advanced", "Advanced Regular Expressions", "regex", "# Lookahead/Lookbehind\n(?=...)   Positive lookahead:  \\d+(?= dollars)  → matches '100' in '100 dollars'\n(?!...)   Negative lookahead:  \\d+(?! dollars)  → matches digits NOT followed by 'dollars'\n(?<=...)  Positive lookbehind: (?<=\\$)\\d+        → matches '100' in '$100'\n(?<!...)  Negative lookbehind: (?<!\\$)\\d+        → matches digits NOT preceded by '$'\n\n# Named groups\n(?P<name>pattern)   Python\n(?<name>pattern)    JS/C#\n\n# Non-greedy quantifiers\n.*?   Match as FEW as possible\n.+?   At least one, but minimal\n\n# Common patterns\nEmail: [\\w.+-]+@[\\w-]+\\.[\\w.]+\nURL: https?://[\\w.-]+(?:/[\\w./-]*)*(?:\\?[\\w=&]*)?\nIP: (?:\\d{1,3}\\.){3}\\d{1,3}\nDate: \\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\\d|3[01])\nPassword: ^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[@$!%]).{8,}$\nSlug: ^[a-z0-9]+(?:-[a-z0-9]+)*$\n\n# Flags: re.IGNORECASE, re.MULTILINE, re.DOTALL, re.VERBOSE", ["regex","regular-expression","pattern","lookahead","lookbehind"]),

        # ═══ PYTHON PACKAGING ═══
        _e("kv_py_packaging", "Python Packaging & Environments", "python", "# Virtual environments\npython -m venv .venv\nsource .venv/bin/activate  # Linux/Mac\npip install -r requirements.txt\npip freeze > requirements.txt\n\n# pyproject.toml (modern standard)\n[project]\nname = 'mypackage'\nversion = '1.0.0'\ndependencies = ['fastapi>=0.100', 'pydantic>=2.0']\n[project.optional-dependencies]\ndev = ['pytest', 'ruff', 'mypy']\n\n# Poetry\npoetry init\npoetry add fastapi\npoetry add --group dev pytest\npoetry install\npoetry build\npoetry publish\n\n# uv (fast, Rust-based)\nuv pip install fastapi\nuv venv\nuv pip compile requirements.in -o requirements.txt\n\n# Package structure\nmypackage/\n  __init__.py\n  core.py\n  utils.py\ntests/\n  test_core.py\npyproject.toml\nREADME.md\n\n# Publishing\npython -m build\ntwine upload dist/*", ["python","packaging","pip","poetry","venv","pyproject"]),

